-- 토픽 수료(graduation/domain/TopicGraduation). 회원·토픽당 1행으로 실습 인증의 "지금 상태"를 적는다.
-- 이 회원이 이 토픽을 수료했는가는 status = 'APPROVED' 하나로만 판단하고, 다른 모듈은 따로 저장하지 않는다.
-- 이름이 비슷한 topic_progress는 회원당 1행으로 "지금 배우고 있는 토픽"을 가리키므로 단위가 다르다.
-- user_id·topic_id는 모듈 경계를 넘는 값이라 FK를 걸지 않는다.
CREATE TABLE "topic_graduations" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" BIGINT NOT NULL,
    "topic_id" BIGINT NOT NULL,
    "status" VARCHAR(30) NOT NULL,
    "approved_at" TIMESTAMPTZ,
    "reward_claimed_at" TIMESTAMPTZ,
    "reward_expires_at" TIMESTAMPTZ,
    "created_at" TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP NOT NULL,
    CONSTRAINT "uk_topic_graduations_user_id_topic_id" UNIQUE ("user_id", "topic_id")
);

-- 실습 인증 영상 제출 이력(graduation/domain/GraduationSubmission). 제출마다 1행이며 지우지 않고 추가만 한다.
-- 영상 교체로 밀려난 제출은 result = 'REPLACED'로 남는다.
CREATE TABLE "graduation_submissions" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "graduation_id" BIGINT NOT NULL REFERENCES "topic_graduations" ("id"),
    "attempt_no" INTEGER NOT NULL,
    "video_object_key" VARCHAR(512) NOT NULL,
    "result" VARCHAR(30) NOT NULL,
    "submitted_at" TIMESTAMPTZ NOT NULL,
    "reviewed_at" TIMESTAMPTZ,
    "reviewer_note" VARCHAR(500),
    "created_at" TIMESTAMP NOT NULL,
    CONSTRAINT "uk_graduation_submissions_graduation_id_attempt_no" UNIQUE ("graduation_id", "attempt_no")
);

-- 운영자 대기 목록(result = 'PENDING', 오래된 제출 순) 조회용
CREATE INDEX "idx_graduation_submissions_result_submitted_at" ON "graduation_submissions" ("result", "submitted_at");
